def count_pairs(root, distance):
    pairs = 0

    def dfs(node):
        """counts[k] = leaves k edges below node, for k <= distance."""
        nonlocal pairs
        counts = [0] * (distance + 1)
        if node is None:
            return counts
        if node.left is None and node.right is None:
            counts[0] = 1
            return counts
        left, right = dfs(node.left), dfs(node.right)
        for a in range(distance + 1):
            for b in range(distance - a - 1):           # (a + 1) + (b + 1) <= distance
                pairs += left[a] * right[b]
        for k in range(distance):
            counts[k + 1] = left[k] + right[k]          # one edge further up
        return counts

    dfs(root)
    return pairs

def count_pairs(root, distance):
    graph, leaves, stack = defaultdict(list), [], [root]
    while stack:
        node = stack.pop()
        kids = [c for c in (node.left, node.right) if c is not None]
        if not kids:
            leaves.append(node)
        for c in kids:
            graph[node].append(c)
            graph[c].append(node)
            stack.append(c)

    leaf_set, found = set(leaves), 0
    for start in leaves:
        seen, frontier = {start}, [start]
        for _ in range(distance):
            nxt = []
            for node in frontier:
                for nb in graph[node]:
                    if nb not in seen:
                        seen.add(nb)
                        nxt.append(nb)
                        found += nb in leaf_set
            frontier = nxt
    return found // 2
